$ec_lang['cs_notes_1_def']='Метода мерења притицаја и отицаја процењује процеђивање мерењем протока на почетку и на крају деонице канала: Q<sub>loss</sub> = Q<sub>in</sub> &minus; Q<sub>out</sub>. Ефикасност транспорта воде E<sub>c</sub> = Q<sub>out</sub> / Q<sub>in</sub>. Годишњи обим претпоставља непрекидан рад са пуним протоком; стварни губитак је мањи за сезонске канале или канале с делимичним протоком.';
$ec_lang['cs_notes_2_term']='Оцене ефикасности';
